"""Workflow analysis tools.

Load, analyze, summarize, and validate ComfyUI workflow JSON.
Handles both UI format (from ComfyUI "Save") and API format
(from "Save API Format" or programmatic use).

These tools give the agent deep understanding of what a workflow does,
what's connected to what, and what can be safely modified.
"""

import json
from pathlib import Path

import httpx

from ._util import to_json
from ..config import COMFYUI_URL

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "load_workflow",
        "description": (
            "Load and analyze a ComfyUI workflow JSON file. "
            "Returns: format type, all nodes with class_type, "
            "connections between nodes (the graph), editable fields "
            "with current values, and a human-readable summary of the pipeline. "
            "This is the main tool for understanding what a workflow does."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "validate_workflow",
        "description": (
            "Validate a workflow against the running ComfyUI instance. "
            "Checks that all node types exist (are installed), that required "
            "inputs are provided, and that connections have compatible types. "
            "Requires ComfyUI to be running."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "get_editable_fields",
        "description": (
            "Get a focused list of all editable fields in a workflow — "
            "the parameters that can be changed without rewiring the graph. "
            "Groups fields by node class_type for easy scanning. "
            "This is useful before modifying a workflow."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
                "class_filter": {
                    "type": "string",
                    "description": (
                        "Optional: only show fields from nodes matching this "
                        "class_type substring (case-insensitive)."
                    ),
                },
            },
            "required": ["path"],
        },
    },
]

# ---------------------------------------------------------------------------
# Core parsing logic
# ---------------------------------------------------------------------------


def _load_json(path_str: str) -> tuple[dict, str | None]:
    """Load JSON from file. Returns (data, error_or_none)."""
    path = Path(path_str)
    if not path.exists():
        return {}, f"File not found: {path_str}"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data, None
    except json.JSONDecodeError as e:
        return {}, f"Invalid JSON: {e}"


def _extract_api_format(data: dict) -> tuple[dict, str]:
    """
    Extract API-format node dict from any workflow format.

    Returns (api_nodes, format_name).
    api_nodes: {node_id_str: {"class_type": ..., "inputs": {...}}}
    """
    # Check for UI format (has "nodes" array)
    if "nodes" in data and isinstance(data["nodes"], list):
        # Prefer embedded API format in extra.prompt
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            return nodes, "ui_with_api"

        # UI-only: convert nodes array
        nodes = {}
        for node in data["nodes"]:
            nid = str(node.get("id", ""))
            class_type = node.get("type", "Unknown")
            widgets = node.get("widgets_values", [])
            nodes[nid] = {
                "class_type": class_type,
                "inputs": {},
                "_widgets_values": widgets,
                "_ui_node": True,
            }
        return nodes, "ui_only"

    # API format: top-level keys are node IDs
    nodes = {
        k: v for k, v in data.items()
        if isinstance(v, dict) and "class_type" in v
    }
    return nodes, "api"


def _trace_connections(nodes: dict) -> list[dict]:
    """
    Trace connections between nodes.

    In API format, a connection is an input value that's a list:
    [source_node_id_str, output_index_int]

    Returns list of connection dicts.
    """
    connections = []
    for target_id, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue  # UI-only nodes don't have connection info
        for input_name, value in sorted(node.get("inputs", {}).items()):
            if isinstance(value, list) and len(value) == 2:
                source_id = str(value[0])
                output_idx = value[1]
                source_class = nodes.get(source_id, {}).get("class_type", "?")
                target_class = node.get("class_type", "?")
                connections.append({
                    "from_node": source_id,
                    "from_class": source_class,
                    "from_output": output_idx,
                    "to_node": target_id,
                    "to_class": target_class,
                    "to_input": input_name,
                })
    return connections


def _find_editable_fields(nodes: dict, class_filter: str = "") -> list[dict]:
    """
    Find all non-connection input fields (the editable parameters).
    """
    fields = []
    filter_lower = class_filter.lower()

    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")
        if filter_lower and filter_lower not in class_type.lower():
            continue

        # He2025: sort for deterministic field order per node
        for field_name, value in sorted(node.get("inputs", {}).items()):
            # Skip connections (2-element list [node_id, output_index])
            if isinstance(value, list) and len(value) == 2:
                continue

            fields.append({
                "node_id": nid,
                "class_type": class_type,
                "field": field_name,
                "value": value,
                "type": type(value).__name__,
            })

    return fields


def _build_summary(nodes: dict, connections: list[dict], fmt: str) -> str:
    """Build a human-readable summary of the workflow pipeline."""
    if not nodes:
        return "Empty workflow (no nodes found)."

    lines = []

    # Class type counts
    class_counts: dict[str, int] = {}
    for node in nodes.values():
        ct = node.get("class_type", "Unknown")
        class_counts[ct] = class_counts.get(ct, 0) + 1

    lines.append(f"{len(nodes)} nodes, {len(connections)} connections")
    lines.append("")

    # Identify pipeline stages by looking at node classes
    loaders = []
    encoders = []
    samplers = []
    threed = []
    outputs = []
    other = []

    for ct in sorted(class_counts.keys()):
        ct_lower = ct.lower()
        if any(k in ct_lower for k in ("load", "checkpoint", "unet", "model")):
            loaders.append(ct)
        elif any(k in ct_lower for k in ("encode", "clip", "conditioning")):
            encoders.append(ct)
        elif any(k in ct_lower for k in ("sample", "sampler", "ksampler", "denoise")):
            samplers.append(ct)
        elif any(k in ct_lower for k in (
            "mesh", "voxel", "3d", "triplane", "gaussian", "splat",
            "point_cloud", "glb", "ply", "obj", "nerf",
            "pose", "camera", "hunyuan3d",
        )):
            threed.append(ct)
        elif any(k in ct_lower for k in ("save", "preview", "output", "combine", "video")):
            outputs.append(ct)
        else:
            other.append(ct)

    if loaders:
        lines.append(f"Loaders: {', '.join(loaders)}")
    if encoders:
        lines.append(f"Encoding: {', '.join(encoders)}")
    if samplers:
        lines.append(f"Sampling: {', '.join(samplers)}")
    if threed:
        lines.append(f"3D Processing: {', '.join(threed)}")
    if outputs:
        lines.append(f"Output: {', '.join(outputs)}")
    if other:
        lines.append(f"Other: {', '.join(other)}")

    # Describe data flow from connections
    if connections:
        lines.append("")
        lines.append("Data flow:")
        # Group by target node to show input sources
        by_target: dict[str, list[dict]] = {}
        for conn in connections:
            key = f"{conn['to_node']} ({conn['to_class']})"
            by_target.setdefault(key, []).append(conn)

        for target, conns in sorted(by_target.items()):
            sources = [f"{c['from_class']}.out[{c['from_output']}]" for c in conns]
            lines.append(f"  {target} <- {', '.join(sources)}")

    if fmt == "ui_only":
        lines.append("")
        lines.append(
            "Note: UI-only format — editable field values not available. "
            "Use an API-format workflow for full analysis."
        )

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Validation (requires live ComfyUI)
# ---------------------------------------------------------------------------

def _validate_against_comfyui(nodes: dict, connections: list[dict]) -> dict:
    """Validate workflow against running ComfyUI instance."""
    errors = []
    warnings = []

    # Fetch all node info
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}/object_info", timeout=30.0)
            resp.raise_for_status()
            all_info = resp.json()
    except httpx.ConnectError:
        return {"error": f"ComfyUI not reachable at {COMFYUI_URL}. Is it running?"}
    except Exception as e:
        return {"error": str(e)}

    # Check each node
    # He2025: sort for deterministic error order
    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")

        # Check node type exists
        if class_type not in all_info:
            errors.append(f"Node [{nid}]: class_type '{class_type}' not installed.")
            continue

        node_schema = all_info[class_type]
        required_inputs = node_schema.get("input", {}).get("required", {})
        optional_inputs = node_schema.get("input", {}).get("optional", {})
        all_known_inputs = {**required_inputs, **optional_inputs}

        # Check required inputs are provided
        node_inputs = node.get("inputs", {})
        for req_name in required_inputs:
            if req_name not in node_inputs:
                errors.append(
                    f"Node [{nid}] {class_type}: missing required input '{req_name}'."
                )

        # Check for unknown inputs
        for inp_name in node_inputs:
            if inp_name not in all_known_inputs:
                warnings.append(
                    f"Node [{nid}] {class_type}: unknown input '{inp_name}' "
                    f"(may be from a different version)."
                )

    # Check connection type compatibility
    for conn in connections:
        source_class = conn["from_class"]
        output_idx = conn["from_output"]
        target_class = conn["to_class"]
        target_input = conn["to_input"]

        # Get source output types
        source_info = all_info.get(source_class, {})
        source_outputs = source_info.get("output", [])
        if output_idx < len(source_outputs):
            source_type = source_outputs[output_idx]
        else:
            errors.append(
                f"Connection {source_class}[{output_idx}] → "
                f"{target_class}.{target_input}: output index out of range."
            )
            continue

        # Get target input type
        target_info = all_info.get(target_class, {})
        all_target_inputs = {
            **target_info.get("input", {}).get("required", {}),
            **target_info.get("input", {}).get("optional", {}),
        }
        target_spec = all_target_inputs.get(target_input)
        if target_spec and isinstance(target_spec, (list, tuple)) and len(target_spec) > 0:
            target_type = target_spec[0]
            # Check type compatibility (exact match or wildcard "*")
            if (
                isinstance(target_type, str)
                and isinstance(source_type, str)
                and target_type != "*"
                and source_type != "*"
                and source_type != target_type
            ):
                errors.append(
                    f"Type mismatch: {source_class}.out[{output_idx}] "
                    f"({source_type}) → {target_class}.{target_input} "
                    f"(expects {target_type})."
                )

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
    }


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_load_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    connections = _trace_connections(nodes)
    editable = _find_editable_fields(nodes)
    summary = _build_summary(nodes, connections, fmt)

    # Build node list for output
    node_list = {}
    for nid, node in nodes.items():
        entry = {
            "class_type": node.get("class_type", ""),
        }
        if not node.get("_ui_node"):
            entry["input_count"] = len(node.get("inputs", {}))
        node_list[nid] = entry

    return to_json({
        "file": path_str,
        "format": fmt,
        "node_count": len(nodes),
        "connection_count": len(connections),
        "editable_field_count": len(editable),
        "summary": summary,
        "nodes": node_list,
        "connections": connections,
        "editable_fields": editable,
    })


def _handle_validate_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only workflow format — can't validate without API format data. "
                "Re-export the workflow using 'Save (API Format)' in ComfyUI, "
                "or use a workflow that has extra.prompt embedded."
            ),
        })

    connections = _trace_connections(nodes)
    result = _validate_against_comfyui(nodes, connections)
    return to_json(result)


def _handle_get_editable_fields(tool_input: dict) -> str:
    path_str = tool_input["path"]
    class_filter = tool_input.get("class_filter", "")

    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only format — field values aren't available. "
                "Use an API-format workflow or one with extra.prompt embedded."
            ),
        })

    fields = _find_editable_fields(nodes, class_filter)

    # Group by class_type for readability
    by_class: dict[str, list[dict]] = {}
    for f in fields:
        by_class.setdefault(f["class_type"], []).append(f)

    return to_json({
        "file": path_str,
        "total_fields": len(fields),
        "fields_by_class": by_class,
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def summarize_workflow_data(data: dict) -> dict:
    """Summarize a raw workflow dict without filesystem I/O.

    Called by the sidebar backend to build context for the system prompt.
    Returns a structured summary dict.
    """
    nodes, fmt = _extract_api_format(data)
    connections = _trace_connections(nodes)
    editable = _find_editable_fields(nodes)
    summary = _build_summary(nodes, connections, fmt)

    node_list = {}
    for nid, node in sorted(nodes.items()):
        entry = {"class_type": node.get("class_type", "")}
        if not node.get("_ui_node"):
            entry["input_count"] = len(node.get("inputs", {}))
        node_list[nid] = entry

    return {
        "format": fmt,
        "node_count": len(nodes),
        "connection_count": len(connections),
        "editable_field_count": len(editable),
        "summary": summary,
        "nodes": node_list,
        "editable_fields": editable,
    }


def handle(name: str, tool_input: dict) -> str:
    """Execute a workflow_parse tool call."""
    try:
        if name == "load_workflow":
            return _handle_load_workflow(tool_input)
        elif name == "validate_workflow":
            return _handle_validate_workflow(tool_input)
        elif name == "get_editable_fields":
            return _handle_get_editable_fields(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except Exception as e:
        return to_json({"error": str(e)})

"""Discovery tools — search for custom node packs and models.

Primary data source: ComfyUI Manager's local JSON registries
(custom-node-list.json, extension-node-map.json, model-list.json).
These ship with ComfyUI-Manager and cover 4,000+ packs and 31,000+ node types.

Secondary: HuggingFace Hub API for broader model search.

Includes freshness tracking to detect stale registry data and suggest updates.
"""

import json
import time
from pathlib import Path

import httpx

from ..config import COMFYUI_URL, CUSTOM_NODES_DIR, MODELS_DIR
from ..rate_limiter import HUGGINGFACE_LIMITER
from ._util import to_json

# ---------------------------------------------------------------------------
# Partner Node registry — officially supported by Comfy-Org + provider
# Update quarterly or when new partnerships are announced.
# ---------------------------------------------------------------------------

PARTNER_NODES: dict[str, dict] = {
    "Hunyuan3D": {
        "provider": "Tencent",
        "capabilities": "text/image/sketch to production 3D mesh",
        "best_for": "final production assets, high-quality 3D generation",
        "url": "https://github.com/Tencent/Hunyuan3D-2",
        "keywords": ["hunyuan3d", "hunyuan 3d", "tencent"],
    },
    "Meshy": {
        "provider": "Meshy",
        "capabilities": "AI mesh generation (stylized assets)",
        "best_for": "game-ready stylized assets, fast stylized generation",
        "url": "https://github.com/meshyai/comfyui-meshy",
        "keywords": ["meshy"],
    },
    "Tripo": {
        "provider": "Tripo",
        "capabilities": "fast 3D prototyping and iteration",
        "best_for": "rapid prototyping, quick iterations",
        "url": "https://github.com/VAST-AI-Research/ComfyUI-Tripo",
        "keywords": ["tripo", "vast-ai"],
    },
    "Rodin": {
        "provider": "Deemos",
        "capabilities": "high-quality 3D generation with geometric detail",
        "best_for": "realistic/detailed models, high geometric fidelity",
        "url": "https://github.com/Deemos-Technology/ComfyUI-Rodin",
        "keywords": ["rodin", "deemos"],
    },
}

# Core node packs that ship with ComfyUI or are maintained by Comfy-Org
_CORE_URLS = frozenset([
    "https://github.com/comfyanonymous/ComfyUI",
])


def _get_source_tier(title: str, url: str) -> str:
    """Determine source tier: 'core', 'partner', or 'community'."""
    url_lower = (url or "").lower()
    title_lower = (title or "").lower()

    # Check core
    if url_lower in _CORE_URLS or "comfyanonymous" in url_lower:
        return "core"

    # Check partner nodes
    for partner_info in PARTNER_NODES.values():
        if partner_info["url"].lower() == url_lower:
            return "partner"
        if any(kw in title_lower for kw in partner_info["keywords"]):
            return "partner"

    return "community"

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "discover",
        "description": (
            "Unified search across ComfyUI Manager registry, CivitAI, and "
            "HuggingFace for custom node packs and models. Returns results "
            "ranked by relevance with installed status. Use this for any "
            "'find me X' or 'what's available for Y' question."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": (
                        "What to search for — model name, node pack, keyword, "
                        "or specific node class_type "
                        "(e.g. 'IPAdapter', 'anime LoRA for SDXL', 'depth controlnet')."
                    ),
                },
                "category": {
                    "type": "string",
                    "enum": ["nodes", "models", "all"],
                    "description": (
                        "What to search: 'nodes' for custom node packs, "
                        "'models' for checkpoints/LoRAs/etc, 'all' for both. "
                        "Default: 'all'."
                    ),
                },
                "sources": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "enum": ["registry", "civitai", "huggingface"],
                    },
                    "description": (
                        "Which sources to search. Default: all applicable "
                        "(registry for nodes, registry+civitai+huggingface for models)."
                    ),
                },
                "model_type": {
                    "type": "string",
                    "description": (
                        "Filter models by type: checkpoint, lora, vae, controlnet, "
                        "embedding, upscaler. Ignored for node searches."
                    ),
                },
                "base_model": {
                    "type": "string",
                    "description": (
                        "Filter by base model: 'sd15', 'sdxl', 'flux', 'sd3', 'pony'. "
                        "Applied to CivitAI; ignored for registry/HuggingFace."
                    ),
                },
                "sort": {
                    "type": "string",
                    "enum": ["most_downloaded", "highest_rated", "newest"],
                    "description": (
                        "CivitAI sort order. Default: 'most_downloaded'. "
                        "Ignored for non-CivitAI sources."
                    ),
                },
                "max_results": {
                    "type": "integer",
                    "description": "Max results per source (default 5).",
                },
            },
            "required": ["query"],
        },
    },
    {
        "name": "find_missing_nodes",
        "description": (
            "Analyze a workflow to find which custom nodes are missing and "
            "suggest where to get them. Checks every node class_type against "
            "the live ComfyUI instance, then looks up missing ones in the "
            "ComfyUI Manager registry. Essential for importing shared workflows."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": (
                        "Path to workflow JSON file. If omitted, uses the "
                        "currently loaded workflow from workflow_patch."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "get_install_instructions",
        "description": (
            "Get installation instructions for a custom node pack or model. "
            "Given a query and source, returns the specific commands needed to "
            "install (git clone for node packs, download path for models). "
            "Bridges the gap between discovery and actual installation."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": (
                        "Name or identifier of the item to install — a node pack "
                        "name/URL, a model name, or a node class_type."
                    ),
                },
                "source": {
                    "type": "string",
                    "enum": ["registry", "civitai", "huggingface"],
                    "description": (
                        "Where to look up install info: 'registry' for ComfyUI "
                        "Manager node packs and models, 'civitai' for CivitAI "
                        "models, 'huggingface' for HuggingFace models. "
                        "Default: 'registry'."
                    ),
                },
            },
            "required": ["query"],
        },
    },
    {
        "name": "check_registry_freshness",
        "description": (
            "Check how fresh the local discovery data is. Reports the age of "
            "ComfyUI Manager registry files (custom-node-list, extension-node-map, "
            "model-list) and local model directories. Helps decide whether to use "
            "local cache or fetch updated data from CivitAI/HuggingFace. "
            "Use refresh=true to clear the in-memory cache and force a reload."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "refresh": {
                    "type": "boolean",
                    "description": (
                        "If true, clears the in-memory registry cache so the next "
                        "search reloads from disk. Default: false."
                    ),
                },
            },
            "required": [],
        },
    },
]

# ---------------------------------------------------------------------------
# Registry cache (loaded once per session from local ComfyUI Manager files)
# ---------------------------------------------------------------------------

_MANAGER_DIR = CUSTOM_NODES_DIR / "ComfyUI-Manager"

_cache: dict = {
    "custom_nodes": None,     # list[dict] from custom-node-list.json
    "extension_map": None,    # dict from extension-node-map.json
    "node_to_pack": None,     # dict[str, dict] — node_type -> pack info
    "model_list": None,       # list[dict] from model-list.json
}

# Freshness tracking — records when each cache was last loaded
_freshness: dict = {
    "custom_nodes_loaded_at": None,   # epoch timestamp
    "extension_map_loaded_at": None,
    "model_list_loaded_at": None,
}

# Staleness thresholds (seconds)
_STALE_THRESHOLD = 7 * 24 * 3600   # 7 days — registry files update infrequently
_WARN_THRESHOLD = 30 * 24 * 3600   # 30 days — strongly suggest update


def _load_custom_nodes() -> list[dict]:
    """Load and cache custom-node-list.json."""
    if _cache["custom_nodes"] is not None:
        return _cache["custom_nodes"]

    path = _MANAGER_DIR / "custom-node-list.json"
    if not path.exists():
        return []

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        _cache["custom_nodes"] = data.get("custom_nodes", [])
        _freshness["custom_nodes_loaded_at"] = time.time()
    except Exception:
        _cache["custom_nodes"] = []

    return _cache["custom_nodes"]


def _load_extension_map() -> dict:
    """Load and cache extension-node-map.json."""
    if _cache["extension_map"] is not None:
        return _cache["extension_map"]

    path = _MANAGER_DIR / "extension-node-map.json"
    if not path.exists():
        return {}

    try:
        _cache["extension_map"] = json.loads(path.read_text(encoding="utf-8"))
        _freshness["extension_map_loaded_at"] = time.time()
    except Exception:
        _cache["extension_map"] = {}

    return _cache["extension_map"]


def _build_node_to_pack() -> dict[str, dict]:
    """Build reverse index: node_type -> {url, title, node_types}."""
    if _cache["node_to_pack"] is not None:
        return _cache["node_to_pack"]

    ext_map = _load_extension_map()
    index = {}
    for url, entry in sorted(ext_map.items()):  # He2025: sorted iteration for deterministic collision resolution
        if not isinstance(entry, list) or len(entry) < 2:
            continue
        node_types = entry[0] if isinstance(entry[0], list) else []
        meta = entry[1] if isinstance(entry[1], dict) else {}
        title = meta.get("title_aux", url.split("/")[-1] if "/" in url else url)

        pack_info = {"url": url, "title": title, "node_count": len(node_types)}
        for nt in node_types:
            index[nt] = pack_info

    _cache["node_to_pack"] = index
    return index


def _load_model_list() -> list[dict]:
    """Load and cache model-list.json."""
    if _cache["model_list"] is not None:
        return _cache["model_list"]

    path = _MANAGER_DIR / "model-list.json"
    if not path.exists():
        return []

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        _cache["model_list"] = data.get("models", [])
        _freshness["model_list_loaded_at"] = time.time()
    except Exception:
        _cache["model_list"] = []

    return _cache["model_list"]


def _is_pack_installed(reference_url: str) -> bool:
    """Check if a custom node pack is installed locally."""
    if not CUSTOM_NODES_DIR.exists():
        return False
    # Extract folder name from git URL
    folder = reference_url.rstrip("/").split("/")[-1]
    if folder.endswith(".git"):
        folder = folder[:-4]
    return (CUSTOM_NODES_DIR / folder).is_dir()


def _is_model_installed(filename: str, save_path: str) -> bool:
    """Check if a model file exists in the expected directory."""
    if not MODELS_DIR.exists():
        return False
    target = MODELS_DIR / save_path / filename
    return target.exists()


