        // Add sidebar button
        const sidebarBtn = document.createElement("button");
        sidebarBtn.className = "comfyui-sidebar-tab";
        sidebarBtn.title = "3D Viewport";
        sidebarBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M12 2L2 7l10 5 10-5-10-5z"/>
            <path d="M2 17l10 5 10-5"/>
            <path d="M2 12l10 5 10-5"/>
        </svg>`;

        // Create sidebar panel content
        panelInstance = new ViewportBridgePanel();
        const panelEl = panelInstance.init();

        // Load CSS
        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = new URL(
            "../css/bridge_panel.css",
            import.meta.url
        ).href;
        document.head.appendChild(link);

        // Register with ComfyUI sidebar if available
        if (app.extensionManager && app.extensionManager.registerSidebarTab) {
            app.extensionManager.registerSidebarTab({
                id: "viewport-3d-bridge",
                icon: "pi pi-box",
                title: "3D Viewport",
                tooltip: "3D Viewport Bridge",
                type: "custom",
                render: (container) => {
                    container.appendChild(panelEl);
                },
            });
        } else {
            // Fallback: append to sidebar directly
            const sidebar = document.querySelector(".comfyui-sidebar");
            if (sidebar) {
                sidebar.appendChild(sidebarBtn);

                let panelVisible = false;
                const panelWrapper = document.createElement("div");
                panelWrapper.className = "vb-panel-wrapper";
                panelWrapper.style.display = "none";
                panelWrapper.appendChild(panelEl);
                document.body.appendChild(panelWrapper);

                sidebarBtn.addEventListener("click", () => {
                    panelVisible = !panelVisible;
                    panelWrapper.style.display = panelVisible ? "block" : "none";
                    sidebarBtn.classList.toggle("active", panelVisible);
                });
            }
        }
    },
});

input.content:
/* ComfyUI 3D Viewport Bridge — Sidebar Panel Styles */

.viewport-bridge-panel {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 12px;
    color: #ddd;
    padding: 8px;
    width: 100%;
    box-sizing: border-box;
}

/* Header */
.vb-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0 10px;
    border-bottom: 1px solid #444;
    margin-bottom: 8px;
}

.vb-title {
    font-size: 13px;
    font-weight: 600;
    color: #eee;
}

.vb-status {
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 10px;
    background: #555;
    color: #aaa;
}

.vb-status-connected {
    background: #1a3a1a;
    color: #6c6;
}

.vb-status-disconnected {
    background: #3a1a1a;
    color: #c66;
}

.vb-status-error {
    background: #3a2a1a;
    color: #ca6;
}

/* Sections */
.vb-section {
    margin-bottom: 12px;
}

.vb-section-title {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #888;
    margin-bottom: 6px;
}

/* Camera info rows */
.vb-camera-info {
    background: #2a2a2a;
    border-radius: 4px;
    padding: 4px 0;
}

.vb-row {
    display: flex;
    justify-content: space-between;
    padding: 3px 8px;
    font-family: "JetBrains Mono", "Cascadia Code", "Consolas", monospace;
    font-size: 11px;
}

.vb-row span:first-child {
    color: #888;
    min-width: 50px;
}

.vb-row span:last-child {
    color: #ccc;
    text-align: right;
}

/* Preset buttons */
.vb-presets {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px;
}

.vb-preset-btn {
    background: #333;
    border: 1px solid #555;
    border-radius: 4px;
    color: #ccc;
    padding: 6px 4px;
    font-size: 11px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
}

.vb-preset-btn:hover {
    background: #444;
    border-color: #777;
    color: #fff;
}

.vb-preset-btn:active {
    background: #555;
}

/* AOV grid */
.vb-aov-grid {
    background: #2a2a2a;
    border-radius: 4px;
    padding: 6px 8px;
    margin-bottom: 6px;
    min-height: 30px;
}

.vb-aov-empty {
    color: #666;
    font-style: italic;
    font-size: 11px;
    text-align: center;
    padding: 4px 0;
}

.vb-aov-card {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 3px 0;
}

.vb-aov-indicator {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #6c6;
    flex-shrink: 0;
}

.vb-aov-name {
    font-size: 11px;
    color: #bbb;
    text-transform: capitalize;
}

.vb-aov-btn {
    width: 100%;
    background: #2a3a4a;
    border: 1px solid #4a6a8a;
    border-radius: 4px;
    color: #8ab;
    padding: 6px;
    font-size: 11px;
    cursor: pointer;
    transition: background 0.15s;
}

.vb-aov-btn:hover {
    background: #3a4a5a;
    color: #acd;
}

.vb-aov-btn:active {
    background: #4a5a6a;
}

/* Fallback panel wrapper (when sidebar API is not available) */
.vb-panel-wrapper {
    position: fixed;
    left: 48px;
    top: 0;
    width: 240px;
    height: 100vh;
    background: #1e1e1e;
    border-right: 1px solid #444;
    z-index: 1000;
    overflow-y: auto;
}

